import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc=new Scanner(System.in);
		int t=sc.nextInt();
		while(t-->0){
		    int n=sc.nextInt();
		    int m=3*n;
		    int[] a=new int[m];
		    for(int i=0;i<m;i++){
		        a[i]=sc.nextInt();
		    }
		    Arrays.sort(a);
		    long[] b=new long[m+1];
		    for(int i=1;i<=m;i++){
		        b[i]=a[m-i];}
		        long[] p=new long[m+1];
		        for(int i=1;i<=m;i++){
		            p[i]=p[i-1]+b[i];}
		            long ans=0;
		            for(int x=0;x<=n;x++){
		                int l=0,r=n-x;
		                while(l<r){
		                    int y=(l+r)/2;
		                    long d=b[x+2*y+1]+b[x+2*y+2]-3L*b[3*n-2*x-y];
		                    if(d>=0)
		                    l=y+1;
		                    else
		                    r=y;
		                    
		                }
		                long cur=2L*p[x]+p[x+2*l]+3L*p[3*n-2*x-l];
		                
		                ans=Math.max(ans,cur);
		                if(l>0){
		                    int y=l-1;
		                    cur=2L*p[x]+p[x+2*y]+3L*p[3*n-2*x-y];
		                    ans=Math.max(ans,cur);
		                }
		            }
		            System.out.println(ans);
		            
		        }
		    }
		    
		}
